#!/usr/bin/env python3
# Auto-generated by ma-provider-tools — do not edit manually.
"""
Fail on upstream review rules that no linter enforces.

Upstream music-assistant/server rejects these patterns in review
(``.github/instructions/music-assistant-standards.instructions.md``), but its
ruff config ignores the matching rules (``BLE001``, ``G004``) or has none, so
they would otherwise surface only at the first upstream PR. Blocking IO,
icon size, manifests and method order are already covered by the upstream
scripts the test workflow runs, so they are not repeated here.

Rules:
    MA001  a new ``aiohttp.ClientSession``; reuse ``self.mass.http_session``
    MA002  a bare or broad ``except`` (``Exception``/``BaseException``) that
           swallows the error silently: it neither re-raises, logs, nor
           uses the caught exception (e.g. collecting it to raise later)
    MA003  an f-string, ``%`` or ``.format()`` message in a logger call; pass
           ``%s`` arguments instead
    MA004  ``asyncio.create_task`` / ``ensure_future`` / ``loop.create_task``
           whose task is discarded; keep a reference or use
           ``self.mass.create_task``
    MA005  direct library database access (``mass.music.database``)
    MA006  a manifest requirement without an exact ``==`` pin or a pinned
           ``git+`` reference

A justified exception is allowed with ``# ma-allow: MA002 <reason>`` as a
trailing comment on the reported line, or as a comment-only line directly
above it (where a formatter would reflow a trailing comment). The reason is
mandatory.

Usage:
    python scripts/check_upstream_rules.py
"""

from __future__ import annotations

import ast
import json
import re
from pathlib import Path

# ruff: noqa: T201

REPO_ROOT = Path(__file__).resolve().parents[1]
SOURCE_ROOT = REPO_ROOT / "provider"
MANIFEST = REPO_ROOT / "provider/manifest.json"

LOG_METHODS = frozenset(
    {"debug", "info", "warning", "warn", "error", "exception", "critical", "log"}
)
BROAD_EXCEPTIONS = frozenset({"Exception", "BaseException"})
TASK_FACTORIES = frozenset({"create_task", "ensure_future"})
ALLOW_RE = re.compile(r"#\s*ma-allow:\s*(MA\d{3})\b[\s:—-]*(\S.*)?$")
PINNED_RE = re.compile(r"^[A-Za-z0-9_.\-\[\], ]+==[^=<>~!*,;]+(\s*;.*)?$")
GIT_PIN_RE = re.compile(r"@\s*git\+\S+@[0-9a-fA-F]{7,40}(#\S*)?(\s*;.*)?$")

HINTS = {
    "MA001": "reuse the shared session `self.mass.http_session`",
    "MA002": "catch the specific exceptions you expect; log or re-raise",
    "MA003": "use %s-style logger arguments, not a pre-formatted message",
    "MA004": "keep a reference to the task or use `self.mass.create_task`",
    "MA005": "providers must not touch the database; use the controllers",
    "MA006": "pin provider requirements exactly (`pkg==1.2.3`)",
}


def find_violations() -> list[str]:
    """Return ``path:line: CODE message`` strings for every unallowed violation."""
    found: list[str] = []
    for path in sorted(SOURCE_ROOT.rglob("*.py")):
        try:
            text = path.read_text(encoding="utf-8")
            tree = ast.parse(text)
        except (SyntaxError, UnicodeDecodeError):
            continue
        rel = path.relative_to(REPO_ROOT).as_posix()
        lines = text.splitlines()
        for lineno, code, detail in _check_tree(tree):
            line = lines[lineno - 1] if 0 < lineno <= len(lines) else ""
            above = lines[lineno - 2] if 1 < lineno <= len(lines) + 1 else ""
            allow = _allowed(line, code)
            if allow is None and above.lstrip().startswith("#"):
                allow = _allowed(above, code)
            if allow is True:
                continue
            if allow is False:
                found.append(
                    f"{rel}:{lineno}: {code} `# ma-allow: {code}` needs a reason"
                )
                continue
            found.append(f"{rel}:{lineno}: {code} {detail} — {HINTS[code]}")
    found.extend(_check_manifest())
    return found


def main() -> int:
    """Report every violation; return 1 when any is found."""
    violations = find_violations()
    if not violations:
        return 0
    print(
        "Upstream music-assistant/server review rules "
        "(.github/instructions/music-assistant-standards.instructions.md):"
    )
    for message in violations:
        print(f"  {message}")
    print(
        "\nFix the code, or add `# ma-allow: <CODE> <reason>` on (or as a "
        "comment line directly above) the reported line when the exception is "
        "deliberate."
    )
    return 1


def _allowed(line: str, code: str) -> bool | None:
    """Return True if allowed, False if allowed without a reason, None otherwise."""
    for match in ALLOW_RE.finditer(line):
        if match.group(1) == code:
            return bool(match.group(2))
    return None


def _check_tree(tree: ast.AST) -> list[tuple[int, str, str]]:
    """Return ``(lineno, code, detail)`` for each AST-level violation."""
    aiohttp_names = _imported_names(tree, "aiohttp")
    out: list[tuple[int, str, str]] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            if _is_client_session(node.func, aiohttp_names):
                out.append((node.lineno, "MA001", "new aiohttp ClientSession"))
            message = _log_message(node)
            if message is not None and _is_preformatted(message):
                out.append((node.lineno, "MA003", "pre-formatted log message"))
        elif isinstance(node, ast.ExceptHandler):
            if _is_broad(node.type) and _is_silent(node) and not _uses_error(node):
                out.append((node.lineno, "MA002", "broad except swallows errors"))
        elif isinstance(node, ast.Expr) and isinstance(node.value, ast.Call):
            if _is_untracked_task(node.value.func):
                out.append((node.lineno, "MA004", "task reference discarded"))
        elif isinstance(node, ast.Attribute):
            if (
                node.attr == "database"
                and isinstance(node.value, ast.Attribute)
                and node.value.attr == "music"
            ):
                out.append((node.lineno, "MA005", "direct database access"))
    return out


def _check_manifest() -> list[str]:
    """Return MA006 violations for unpinned manifest requirements."""
    if not MANIFEST.is_file():
        return []
    try:
        requirements = json.loads(MANIFEST.read_text(encoding="utf-8")).get(
            "requirements", []
        )
    except (json.JSONDecodeError, AttributeError):
        return []
    rel = MANIFEST.relative_to(REPO_ROOT).as_posix()
    return [
        f"{rel}: MA006 requirement `{req}` is not pinned — {HINTS['MA006']}"
        for req in requirements
        if isinstance(req, str) and not (PINNED_RE.match(req) or GIT_PIN_RE.search(req))
    ]


def _imported_names(tree: ast.AST, module: str) -> set[str]:
    """Return local names bound by ``from <module> import ClientSession``."""
    names: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom) and node.module == module:
            for alias in node.names:
                if alias.name == "ClientSession":
                    names.add(alias.asname or alias.name)
    return names


def _is_client_session(func: ast.expr, local_names: set[str]) -> bool:
    """Return whether a call target constructs an aiohttp ClientSession."""
    if isinstance(func, ast.Name):
        return func.id in local_names
    return (
        isinstance(func, ast.Attribute)
        and func.attr == "ClientSession"
        and isinstance(func.value, ast.Name)
        and func.value.id == "aiohttp"
    )


def _log_message(call: ast.Call, *, any_args: bool = False) -> ast.expr | None:
    """
    Return the message argument of a logger call, or None if not a logger call.

    :param call: The call to inspect.
    :param any_args: Return the call itself for a logger call without a message.
    """
    func = call.func
    if not isinstance(func, ast.Attribute) or func.attr not in LOG_METHODS:
        return None
    if "log" not in ast.unparse(func.value).lower():
        return None
    index = 1 if func.attr == "log" else 0
    if len(call.args) > index:
        return call.args[index]
    return call if any_args else None


def _is_preformatted(message: ast.expr) -> bool:
    """Return whether a log message is formatted before the logger sees it."""
    if isinstance(message, ast.JoinedStr):
        return any(isinstance(v, ast.FormattedValue) for v in message.values)
    if isinstance(message, ast.BinOp) and isinstance(message.op, ast.Mod):
        return isinstance(message.left, ast.Constant) and isinstance(
            message.left.value, str
        )
    return (
        isinstance(message, ast.Call)
        and isinstance(message.func, ast.Attribute)
        and message.func.attr == "format"
        and isinstance(message.func.value, ast.Constant)
    )


def _is_broad(exc_type: ast.expr | None) -> bool:
    """Return whether an except clause catches everything."""
    if exc_type is None:
        return True
    candidates = exc_type.elts if isinstance(exc_type, ast.Tuple) else [exc_type]
    return any(isinstance(c, ast.Name) and c.id in BROAD_EXCEPTIONS for c in candidates)


def _uses_error(handler: ast.ExceptHandler) -> bool:
    """Return whether the handler body reads the bound exception (``as err``)."""
    if handler.name is None:
        return False
    return any(
        isinstance(node, ast.Name) and node.id == handler.name
        for stmt in handler.body
        for node in ast.walk(stmt)
    )


def _is_silent(handler: ast.ExceptHandler) -> bool:
    """Return whether a handler neither raises nor logs, ignoring nested functions."""
    stack: list[ast.AST] = list(handler.body)
    while stack:
        node = stack.pop()
        if isinstance(node, ast.Raise):
            return False
        if isinstance(node, ast.Call) and _log_message(node, any_args=True) is not None:
            return False
        if isinstance(node, ast.FunctionDef | ast.AsyncFunctionDef | ast.Lambda):
            continue
        stack.extend(ast.iter_child_nodes(node))
    return True


def _is_untracked_task(func: ast.expr) -> bool:
    """Return whether a bare call creates an asyncio task nobody keeps."""
    if not isinstance(func, ast.Attribute) or func.attr not in TASK_FACTORIES:
        return False
    receiver = func.value
    if isinstance(receiver, ast.Name) and receiver.id == "asyncio":
        return True
    if isinstance(receiver, ast.Call):
        target = ast.unparse(receiver.func)
        return target.endswith(("get_running_loop", "get_event_loop"))
    return ast.unparse(receiver).lower().endswith("loop")


if __name__ == "__main__":
    raise SystemExit(main())
